create table campaigns(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,name text not null,channel_id int not null references channels,team_id int references teams,config jsonb not null,status text not null default 'draft' check(status in ('draft','scheduled','running','paused','completed','cancelled')),next_at timestamptz,created_by int references users,created_at timestamptz not null default now(),launched_at timestamptz,finished_at timestamptz,detail text);
create table campaign_preferences(contact_id int primary key references contacts,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,allowed bool not null default false,source text not null,actor_id int references users,updated_at timestamptz not null default now());
create table campaign_recipients(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,campaign_id int not null references campaigns,contact_id int not null references contacts,conversation_id int references conversations,state text not null default 'pending' check(state in ('pending','check_required','sent','skipped','cancelled')),message_id bigint references messages,external_id text,attempt_at timestamptz,sent_at timestamptz,interacted_at timestamptz,response_message_id bigint references messages,attempts int not null default 0,detail text,unique(campaign_id,contact_id));
create table campaign_events(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,campaign_id int references campaigns,recipient_id bigint references campaign_recipients,actor_id int references users,type text not null,detail text,at timestamptz not null default now());
create table campaign_channel_clock(channel_id int primary key references channels,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,next_at timestamptz not null default now());
create index campaign_due on campaigns(next_at) where status in ('scheduled','running');
create index campaign_pending on campaign_recipients(campaign_id,id) where state='pending';
create index campaign_response on campaign_recipients(contact_id,sent_at desc) where state='sent';
do $$ declare r record;begin
 for r in select * from (values('campaigns','channels,channel_id,teams,team_id,users,created_by'),('campaign_preferences','contacts,contact_id,users,actor_id'),('campaign_recipients','campaigns,campaign_id,contacts,contact_id,conversations,conversation_id,messages,message_id,messages,response_message_id'),('campaign_events','campaigns,campaign_id,campaign_recipients,recipient_id,users,actor_id'),('campaign_channel_clock','channels,channel_id')) v(t,a) loop
 execute format('alter table %I enable row level security',r.t);execute format('alter table %I force row level security',r.t);execute format($f$create policy tenant_iso on %I using(tenant_id=nullif(current_setting('app.tenant',true),'')::int) with check(tenant_id=nullif(current_setting('app.tenant',true),'')::int)$f$,r.t);
 execute format('create trigger fk_guard before insert or update on %I for each row execute function fk_guard(%s)',r.t,(select string_agg(quote_literal(x),',') from unnest(string_to_array(r.a,',')) x));
 end loop;end $$;
